import { loadFont } from "@remotion/google-fonts/SchibstedGrotesk";
import React, { forwardRef, useId, useImperativeHandle, useMemo, useRef, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

// A component's schedule, kept apart from its drawing: which elements the
// animation has (an entry, a word, a finale), when each starts and how long
// it runs. The schedule is a pure function of the props, so it can be read
// without rendering anything, and a `timing` prop can move, trim or stretch
// single elements without touching the code that draws them.
//
//   // timeline.ts, next to the component
//   export const titleTimeline = defineTimeline<TitleElementId, TitleProps>(
//     ({ words = WORDS }, { length }) =>
//       words.map((word, k) => ({
//         id: `word:${k}`,
//         lane: "Words",
//         label: word,
//         start: k * 8,
//         length: 8,
//         follows: k > 0 ? `word:${k - 1}` : undefined,
//         beats: { rise: 12 },
//       })),
//   );
//
//   // index.tsx
//   const tl = useTimeline(titleTimeline, props, length, timing);
//   const word = tl.get("word:0");
//   interpolate(t, [word.start, word.start + word.beat("rise")], [0, 1]);
//
// Every number is in frames of the 30 fps scene timeline, after `delay` and
// `speed`: those still apply to the whole animation, `timing` works inside it.
// Element ids are public API: a saved `timing` refers to them, so an id once
// shipped keeps its meaning.

/** One timed part of an animation, as its schedule lays it out. */
interface TimelineElement<Id extends string = string> {
  /** Stable name a `timing` override refers to: `entry:0`, `finale`. */
  id: Id;
  /** Row the element sits on in a timeline view. */
  lane: string;
  /** What the element shows, for people reading the timeline. */
  label: string;
  /** First frame of the element. */
  start: number;
  /** Frames until the next element of the lane takes over, or the end. */
  length: number;
  /**
   * The element this one comes after. When that element's end moves, this
   * one moves with it, keeping the gap between them.
   */
  follows?: Id;
  /**
   * Named frame counts inside the element, measured from its start: how long
   * a roll takes, when a second part begins. `stretch` scales them.
   */
  beats?: Record<string, number>;
}

/** A change to one element, made from outside the component. */
interface TimingOverride {
  /** New first frame. Wins over the shift from `follows`. */
  start?: number;
  /** New length, trimming or extending the element. Wins over `stretch`. */
  length?: number;
  /** Multiplies the length and every beat: 2 plays the element half as fast. */
  stretch?: number;
  /** Stops following: the element keeps its own start when the one before moves. */
  detach?: boolean;
}

/** Overrides by element id: the `timing` prop of a component. */
type Timing<Id extends string = string> = Partial<
  Record<Id, TimingOverride>
>;

/** A component's schedule: props and the scene length in, elements out. */
type Schedule<Id extends string, Props> = (
  props: Props,
  scene: { length: number },
) => TimelineElement<Id>[];

/** An element after `timing` has been applied. */
interface ResolvedElement<Id extends string = string>
  extends TimelineElement<Id> {
  /** `start + length`. */
  end: number;
  beats: Record<string, number>;
  /** A beat by name, stretched. Throws on a name the schedule didn't set. */
  beat(name: string): number;
  /**
   * 0 → 1 over the element, or over its first `beat` frames when a beat is
   * named. Clamped on both sides.
   */
  progress(frame: number, beat?: string): number;
}

interface ResolvedTimeline<Id extends string = string> {
  /** All elements, in the order the schedule returned them. */
  elements: ResolvedElement<Id>[];
  /** An element by id. Throws on an id the schedule didn't return. */
  get(id: Id): ResolvedElement<Id>;
  /** The elements of one lane, in order. */
  lane(name: string): ResolvedElement<Id>[];
}

/** Declares a schedule. Elements come back in time order. */
function defineTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
): Schedule<Id, Props> {
  return schedule;
}

/** Applies `timing` to a schedule's elements and carries the `follows` chains. */
function resolve<Id extends string>(
  elements: TimelineElement<Id>[],
  timing: Timing<Id> = {},
): ResolvedTimeline<Id> {
  const byId = new Map<Id, TimelineElement<Id>>(elements.map((e) => [e.id, e]));
  const done = new Map<Id, ResolvedElement<Id>>();
  const visiting = new Set<Id>();

  const place = (element: TimelineElement<Id>): ResolvedElement<Id> => {
    const known = done.get(element.id);
    if (known) return known;
    if (visiting.has(element.id)) {
      throw new Error(`timeline: "${element.id}" follows itself`);
    }
    visiting.add(element.id);

    const override: TimingOverride = timing[element.id] ?? {};
    const stretch = override.stretch ?? 1;
    const beats: Record<string, number> = {};
    for (const [name, frames] of Object.entries(element.beats ?? {})) {
      beats[name] = frames * stretch;
    }

    let start = element.start;
    const leader = element.follows ? byId.get(element.follows) : undefined;
    if (leader && !override.detach) {
      // The leader's end moved by this much; this element moves as far.
      start += place(leader).end - (leader.start + leader.length);
    }
    if (override.start !== undefined) start = override.start;
    const length = override.length ?? element.length * stretch;

    const beat = (name: string) => {
      const frames = beats[name];
      if (frames === undefined) {
        throw new Error(`timeline: "${element.id}" has no beat "${name}"`);
      }
      return frames;
    };
    const resolved: ResolvedElement<Id> = {
      ...element,
      start,
      length,
      end: start + length,
      beats,
      beat,
      progress: (frame, name) => {
        const span = name === undefined ? length : beat(name);
        if (span <= 0) return frame >= start ? 1 : 0;
        return Math.min(1, Math.max(0, (frame - start) / span));
      },
    };
    visiting.delete(element.id);
    done.set(element.id, resolved);
    return resolved;
  };

  const all = elements.map(place);
  return {
    elements: all,
    get: (id) => {
      const element = done.get(id);
      if (!element) throw new Error(`timeline: no element "${id}"`);
      return element;
    },
    lane: (name) => all.filter((e) => e.lane === name),
  };
}

/**
 * The component side: runs the schedule and applies `timing`, once per
 * change of its inputs. `length` is the scene length the schedule fits into,
 * in the same frames the component counts.
 */
function useTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
  props: Props,
  length: number,
  timing?: Timing<Id>,
): ResolvedTimeline<Id> {
  return useMemo(
    () => resolve(schedule(props, { length }), timing),
    [schedule, props, length, timing],
  );
}

// The first tile drawing in, three quarter turns around its corner, the
// rosette mirrored across the axis, the block slid sideways and then up and
// down into a wall, and the first tile picked out at the end; the camera
// pulls back in three moves while it builds. Frames on the 30 fps scene
// timeline, after `delay` and `speed`. The ids are public: a saved `timing`
// prop refers to them.

type PatternTileElementId =
  | "tile"
  | "labels"
  | `camera:${number}`
  | `rotate:${number}`
  | "mirror"
  | "slide-x"
  | "slide-y"
  | "focus";

/** The scene's timing does not depend on its props. */
type PatternTileTimingProps = object;

// `tile` fades in (`appear`), its edge draws (`edge`) and fades from
// `edgeFadeAt`, its disc sweeps from `sweepAt` and its bar grows from
// `growAt`. `camera:<k>` is one pull back, holding between them. Each
// `rotate:<k>` turns a copy a quarter further; the pivot dot shows from
// `pivotIn` to `pivotOn` of the first and fades `pivotOut` after the last.
// `mirror` flips the rosette; its axis shows from `axisIn`, grows until
// `axisGrown` and fades `axisOut` after it ends.
const patternTileTimeline = defineTimeline<
  PatternTileElementId,
  PatternTileTimingProps
>((): TimelineElement<PatternTileElementId>[] => [
  {
    id: "tile",
    lane: "Tile",
    label: "first tile",
    start: 0,
    length: 28,
    beats: {
      appear: 12,
      edge: 22,
      edgeFadeAt: 28,
      edgeFade: 16,
      sweepAt: 6,
      sweep: 18,
      growAt: 14,
      grow: 14,
    },
  },
  {
    id: "labels",
    lane: "Labels",
    label: "steps",
    start: 4,
    length: 14,
  },
  {
    id: "camera:0",
    lane: "Camera",
    label: "pull back",
    start: 24,
    length: 40,
  },
  ...[32, 43, 54].map(
    (start, k): TimelineElement<PatternTileElementId> => ({
      id: `rotate:${k}`,
      lane: "Moves",
      label: `rotate ${90 * (k + 1)}°`,
      start,
      length: 11,
      follows: k > 0 ? `rotate:${k - 1}` : "tile",
      beats: { pivotIn: -4, pivotOn: 2, pivotOut: 8 },
    }),
  ),
  {
    id: "camera:1",
    lane: "Camera",
    label: "pull back",
    start: 66,
    length: 28,
    follows: "camera:0",
  },
  {
    id: "mirror",
    lane: "Moves",
    label: "mirror",
    start: 68,
    length: 24,
    follows: "rotate:2",
    beats: { axisIn: -4, axisOn: 4, axisGrown: 8, axisOut: 8 },
  },
  {
    id: "camera:2",
    lane: "Camera",
    label: "pull back",
    start: 96,
    length: 28,
    follows: "camera:1",
  },
  {
    id: "slide-x",
    lane: "Moves",
    label: "translate sideways",
    start: 98,
    length: 18,
    follows: "mirror",
  },
  {
    id: "slide-y",
    lane: "Moves",
    label: "translate up and down",
    start: 116,
    length: 18,
    follows: "slide-x",
  },
  {
    id: "focus",
    lane: "Focus",
    label: "first tile picked out",
    start: 140,
    length: 16,
    follows: "slide-y",
  },
]);

const { fontFamily: sans } = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

interface PatternTileProps {
  steps?: [string, string, string, string];
  unit?: string;
  accent?: string;
  /** How close the camera starts on the first tile (1 = the whole wall). */
  zoom?: number;
  /** Dim the wall at the end so the first tile stands out. */
  highlight?: boolean;
  /** Color of the active step, the counter and the highlighted tile; overrides the theme ink. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the labels. Load it yourself; Schibsted Grotesk by default. */
  fontFamily?: string;
  /** Size of the wall and labels, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  /** Film grain over the scene. */
  grain?: boolean;
  theme?: "dark" | "light";
  speed?: number;
  /**
   * Moves, trims or stretches the first tile, the camera pulls, each turn,
   * the mirror, the two slides and the closing focus, by the ids in
   * `./timeline`. Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<PatternTileElementId>;
}

// gradients.sh "fluted" palette, laid across the whole wall in grid space so
// every quarter-disc is a slice of one continuous field.
const FLUTED = ["#1d2a8f", "#2f7bff", "#ff7a3d", "#ffe2c4"] as const;

const COLS = 12;
const ROWS = 6;
const HERO: [number, number] = [4, 2];
const MIRROR_X = 6;

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_TURN = Easing.bezier(0.55, 0, 0.2, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    key: "rgba(255,255,255,0.04)",
    surface: "#141416",
    disc: "#E6E5E1",
    bar: "#8E8C88",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    edge: "rgba(255,255,255,0.16)",
    dim: 0.6,
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    key: "rgba(255,255,255,0.85)",
    surface: "#EAE8E2",
    disc: "#18181A",
    bar: "#8A8882",
    fg: "#121214",
    muted: "#6E6C67",
    edge: "rgba(18,18,20,0.18)",
    dim: 0.55,
    grain: 0.045,
  },
} as const;

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={23}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function pie(r: number, a: number, bleed: number) {
  if (a >= Math.PI / 2 - 1e-6) {
    const b = bleed.toFixed(3);
    const rr = r.toFixed(3);
    return `M-${b} -${b} L${rr} -${b} L${rr} 0 A${rr} ${rr} 0 0 1 0 ${rr} L-${b} ${rr} Z`;
  }
  const ex = r * Math.cos(a);
  const ey = r * Math.sin(a);
  return `M0 0 L${r.toFixed(3)} 0 A${r.toFixed(3)} ${r.toFixed(3)} 0 0 1 ${ex.toFixed(3)} ${ey.toFixed(3)} Z`;
}

interface Look {
  disc: string;
  bar: string;
  motif: number;
}

interface TileInst {
  key: string;
  tf: string;
  sweep: number;
  grow: number;
}

interface Group {
  key: string;
  tf: string;
  tiles: TileInst[];
}

function Motif({
  T,
  look,
  sweep,
  grow,
  bleed,
  part = "both",
}: {
  T: number;
  look: Look;
  sweep: number;
  grow: number;
  bleed: number;
  part?: "both" | "disc" | "bar";
}) {
  return (
    <g opacity={look.motif}>
      {sweep > 0 && part !== "bar" ? (
        <path
          d={pie(0.6 * T, (Math.PI / 2) * Math.min(1, sweep), bleed)}
          fill={look.disc}
        />
      ) : null}
      {grow > 0 && part !== "disc" ? (
        <rect
          x={0.72 * T}
          y={0.12 * T}
          width={0.16 * T}
          height={0.5 * T * grow}
          fill={look.bar}
        />
      ) : null}
    </g>
  );
}

function GroupView({
  group,
  T,
  surface,
  look,
  bleed,
  field,
  maskId,
}: {
  group: Group;
  T: number;
  surface: string;
  look: Look;
  bleed: number;
  field: string;
  maskId: string;
}) {
  const box = {
    x: -COLS * T,
    y: -ROWS * T,
    width: COLS * T * 3,
    height: ROWS * T * 3,
  };
  const white: Look = { disc: "#FFFFFF", bar: "#FFFFFF", motif: 1 };
  return (
    <g>
      <g transform={group.tf || undefined}>
        {group.tiles.map((tile) => (
          <rect
            key={`s${tile.key}`}
            transform={tile.tf}
            x={0}
            y={0}
            width={T}
            height={T}
            fill={surface}
            stroke={surface}
            strokeWidth={0.8}
          />
        ))}
        {group.tiles.map((tile) => (
          <g key={`b${tile.key}`} transform={tile.tf}>
            <Motif
              T={T}
              look={look}
              sweep={tile.sweep}
              grow={tile.grow}
              bleed={bleed}
              part="bar"
            />
          </g>
        ))}
      </g>
      <mask id={maskId} maskUnits="userSpaceOnUse" {...box}>
        <g transform={group.tf || undefined}>
          {group.tiles.map((tile) => (
            <g key={`m${tile.key}`} transform={tile.tf}>
              <Motif
                T={T}
                look={white}
                sweep={tile.sweep}
                grow={tile.grow}
                bleed={bleed}
                part="disc"
              />
            </g>
          ))}
        </g>
      </mask>
      <rect
        {...box}
        fill={field}
        mask={`url(#${maskId})`}
        opacity={look.motif}
      />
    </g>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function PatternTileBase(props: PatternTileProps) {
  const {
    steps = ["tile", "rotate 90°", "mirror", "translate"],
    unit = "tiles",
    accent = "#3B5BFD",
    zoom = 2.8,
    highlight = true,
    ink,
    background,
    fontFamily = sans,
    scale = 1,
    delay = 0,
    grain = true,
    theme = "dark",
    speed = 1,
    timing,
  } = props;
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    patternTileTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const tileEl = tl.get("tile");
  const cams = [0, 1, 2].map((k) => tl.get(`camera:${k}`));
  const rots = [0, 1, 2].map((k) => tl.get(`rotate:${k}`));
  const mirrorEl = tl.get("mirror");
  const MIRROR: [number, number] = [mirrorEl.start, mirrorEl.end];
  const slideX = tl.get("slide-x");
  const SLIDE_H: [number, number] = [slideX.start, slideX.end];
  const slideY = tl.get("slide-y");
  const SLIDE_V: [number, number] = [slideY.start, slideY.end];
  const focusEl = tl.get("focus");
  const labelsEl = tl.get("labels");
  const u = H / 720;
  const c = THEMES[theme];
  const fg = ink ?? c.fg;
  const bg =
    background === "transparent" ? "transparent" : (background ?? c.bg);

  const labelF = 18 * u;
  const labelGap = 30 * u;
  const T = Math.min((W * 0.84) / COLS, (H * 0.66) / ROWS);
  const gridW = T * COLS;
  const gridH = T * ROWS;
  const blockTop = (H - (gridH + labelGap + labelF)) / 2;
  const pcx = W / 2;
  const pcy = blockTop + gridH / 2;

  const camAt = (k: number[], v: number[]) =>
    interpolate(t, k, v, { ...CLAMP, easing: EASE_IO });
  const camK = cams.flatMap((e) => [e.start, e.end]);
  const logS = camAt(camK, [
    Math.log(zoom),
    Math.log(2.05),
    Math.log(2.05),
    Math.log(1.45),
    Math.log(1.45),
    0,
  ]);
  const S = Math.exp(logS);
  const camX = camAt(camK, [4.5, 5, 5, 6, 6, 6]);
  const camY = camAt(camK, [2.5, 3, 3, 3, 3, 3]);

  const tileAt = tileEl.start;
  const appear = interpolate(
    t,
    [tileAt, tileAt + tileEl.beat("appear")],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_OUT,
    },
  );
  const sweepAt = tileAt + tileEl.beat("sweepAt");
  const sweep = interpolate(
    t,
    [sweepAt, sweepAt + tileEl.beat("sweep")],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_IO,
    },
  );
  const growAt = tileAt + tileEl.beat("growAt");
  const grow = interpolate(t, [growAt, growAt + tileEl.beat("grow")], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const edgeDraw = interpolate(
    t,
    [tileAt, tileAt + tileEl.beat("edge")],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_IO,
    },
  );
  const edgeFadeAt = tileAt + tileEl.beat("edgeFadeAt");
  const edgeFade = interpolate(
    t,
    [edgeFadeAt, edgeFadeAt + tileEl.beat("edgeFade")],
    [1, 0],
    CLAMP,
  );

  const rotP = rots.map((e) =>
    interpolate(t, [e.start, e.end], [0, 1], { ...CLAMP, easing: EASE_TURN }),
  );
  const flip = interpolate(t, MIRROR, [1, -1], { ...CLAMP, easing: EASE_IO });
  const slideH = interpolate(t, SLIDE_H, [0, 1], { ...CLAMP, easing: EASE_IO });
  const slideV = interpolate(t, SLIDE_V, [0, 1], { ...CLAMP, easing: EASE_IO });
  const focus = highlight
    ? interpolate(t, [focusEl.start, focusEl.end], [0, 1], {
        ...CLAMP,
        easing: EASE_IO,
      })
    : 0;

  const look: Look = {
    disc: c.disc,
    bar: c.bar,
    motif: 1 - (1 - c.dim) * focus,
  };
  const heroTf = `translate(${HERO[0] * T} ${HERO[1] * T})`;
  const rotTf = (angle: number) =>
    `${heroTf} rotate(${angle.toFixed(3)} ${T} ${T})`;
  const mirTf = (sx: number) =>
    `translate(${MIRROR_X * T} 0) scale(${sx.toFixed(4)} 1) translate(${-MIRROR_X * T} 0)`;
  const tile = (key: string, tf: string, sw = 1, gr = 1): TileInst => ({
    key,
    tf,
    sweep: sw,
    grow: gr,
  });
  const rosette = (prefix: string, pre = ""): TileInst[] =>
    [0, 90, 180, 270].map((ang) =>
      tile(`${prefix}${ang}`, `${pre} ${rotTf(ang)}`.trim()),
    );
  const blockTiles = (prefix: string, pre = ""): TileInst[] => [
    ...rosette(`${prefix}a`, pre),
    ...rosette(`${prefix}m`, `${pre} ${mirTf(-1)}`.trim()),
  ];

  const still: TileInst[] = [tile("hero", rotTf(0), sweep, grow)];
  const under: Group[] = [];
  const over: Group[] = [];
  rotP.forEach((p, k) => {
    if (p >= 1) still.push(tile(`r${k}`, rotTf(90 * (k + 1))));
    else if (p > 0)
      over.push({
        key: `rot${k}`,
        tf: "",
        tiles: [tile(`r${k}`, rotTf(90 * k + 90 * p))],
      });
  });
  if (t >= MIRROR[1]) still.push(...rosette("m", mirTf(-1)));
  else if (t >= MIRROR[0])
    under.push({ key: "mir", tf: mirTf(flip), tiles: rosette("m") });
  for (const dx of [-4, 4]) {
    if (t >= SLIDE_H[1])
      still.push(...blockTiles(`h${dx}`, `translate(${dx * T} 0)`));
    else if (t >= SLIDE_H[0])
      over.push({
        key: `h${dx}`,
        tf: `translate(${(dx * T * slideH).toFixed(3)} 0)`,
        tiles: blockTiles(`h${dx}`),
      });
  }
  for (const dy of [-2, 2]) {
    for (const dx of [-4, 0, 4]) {
      const pre = `translate(${dx * T} 0)`;
      if (t >= SLIDE_V[1])
        still.push(
          ...blockTiles(`v${dx}${dy}`, `translate(${dx * T} ${dy * T})`),
        );
      else if (t >= SLIDE_V[0])
        over.push({
          key: `v${dx}${dy}`,
          tf: `translate(0 ${(dy * T * slideV).toFixed(3)})`,
          tiles: blockTiles(`v${dx}${dy}`, pre),
        });
    }
  }
  const stillGroup: Group = { key: "still", tf: "", tiles: still };
  const heroLook: Look = { disc: fg, bar: fg, motif: 1 };
  const gid = `pt${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const field = `url(#${gid}f)`;
  const fdx = Math.sin(t / 48) * 0.35 * T;

  const pivotO =
    interpolate(
      t,
      [
        rots[0].start + rots[0].beat("pivotIn"),
        rots[0].start + rots[0].beat("pivotOn"),
      ],
      [0, 1],
      CLAMP,
    ) *
    interpolate(
      t,
      [rots[2].end, rots[2].end + rots[2].beat("pivotOut")],
      [1, 0],
      CLAMP,
    );
  const axisIn = MIRROR[0] + mirrorEl.beat("axisIn");
  const axisO =
    interpolate(
      t,
      [axisIn, MIRROR[0] + mirrorEl.beat("axisOn")],
      [0, 1],
      CLAMP,
    ) *
    interpolate(
      t,
      [MIRROR[1], MIRROR[1] + mirrorEl.beat("axisOut")],
      [1, 0],
      CLAMP,
    );
  const axisGrow = interpolate(
    t,
    [axisIn, MIRROR[0] + mirrorEl.beat("axisGrown")],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_OUT,
    },
  );

  const tiles =
    t < rots[0].end
      ? 1
      : t < rots[1].end
        ? 2
        : t < rots[2].end
          ? 3
          : t < MIRROR[1]
            ? 4
            : t < SLIDE_H[1]
              ? 8
              : t < SLIDE_V[1]
                ? 24
                : 72;

  const phase =
    t < rots[0].start ? 0 : t < MIRROR[0] - 2 ? 1 : t < SLIDE_H[0] - 2 ? 2 : 3;
  const allDone = t >= focusEl.start;

  const tx = pcx - camX * T * S;
  const ty = pcy - camY * T * S;
  const edgeLen = 4 * T;
  const labelIn = interpolate(t, [labelsEl.start, labelsEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 70% 80% at 45% 35%, ${c.key}, transparent 70%)`,
        }}
      />
      <ScaleLayer scale={scale}>
        <svg
          width={W}
          height={H}
          style={{ position: "absolute", inset: 0 }}
          aria-hidden
        >
          <g
            transform={`translate(${tx.toFixed(3)} ${ty.toFixed(3)}) scale(${S.toFixed(5)})`}
            opacity={appear}
          >
            <defs>
              <linearGradient
                id={`${gid}f`}
                gradientUnits="userSpaceOnUse"
                x1={fdx}
                y1={0}
                x2={COLS * T + fdx}
                y2={ROWS * T}
              >
                <stop offset={0.04} stopColor={FLUTED[0]} />
                <stop offset={0.36} stopColor={FLUTED[1]} />
                <stop offset={0.68} stopColor={FLUTED[2]} />
                <stop offset={0.96} stopColor={FLUTED[3]} />
              </linearGradient>
            </defs>
            {under.map((g) => (
              <GroupView
                key={g.key}
                group={g}
                T={T}
                surface={c.surface}
                bleed={0.6 / S}
                look={look}
                field={field}
                maskId={`${gid}${g.key}`}
              />
            ))}
            <GroupView
              group={stillGroup}
              T={T}
              surface={c.surface}
              look={look}
              bleed={0.6 / S}
              field={field}
              maskId={`${gid}still`}
            />
            {over.map((g) => (
              <GroupView
                key={g.key}
                group={g}
                T={T}
                surface={c.surface}
                bleed={0.6 / S}
                look={look}
                field={field}
                maskId={`${gid}${g.key}`}
              />
            ))}
            {focus > 0 ? (
              <g transform={heroTf} opacity={focus}>
                <Motif T={T} look={heroLook} sweep={1} grow={1} bleed={0} />
              </g>
            ) : null}
            {pivotO > 0 ? (
              <circle
                cx={(HERO[0] + 1) * T}
                cy={(HERO[1] + 1) * T}
                r={(5 * u) / S}
                fill={accent}
                opacity={pivotO}
              />
            ) : null}
            {axisO > 0 ? (
              <rect
                x={MIRROR_X * T - (0.75 * u) / S}
                y={(HERO[1] + 1) * T - 1.25 * T * axisGrow}
                width={(1.5 * u) / S}
                height={2.5 * T * axisGrow}
                fill={accent}
                opacity={axisO}
              />
            ) : null}
            {edgeFade > 0 ? (
              <rect
                x={HERO[0] * T}
                y={HERO[1] * T}
                width={T}
                height={T}
                fill="none"
                stroke={c.edge}
                strokeWidth={1.2 / S}
                strokeDasharray={`${edgeLen * edgeDraw} ${edgeLen}`}
                opacity={edgeFade}
              />
            ) : null}
          </g>
        </svg>

        <div
          style={{
            position: "absolute",
            left: pcx - gridW / 2,
            width: gridW,
            top: blockTop + gridH + labelGap,
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            fontFamily,
            fontWeight: 500,
            fontSize: labelF,
            lineHeight: 1,
            letterSpacing: "-0.01em",
            whiteSpace: "nowrap",
            opacity: labelIn,
          }}
        >
          <div style={{ display: "flex", alignItems: "center", gap: 14 * u }}>
            {steps.map((s, i) => {
              const active = i === phase && !allDone;
              const done = i < phase || allDone;
              return (
                <div
                  key={s}
                  style={{ display: "flex", alignItems: "center", gap: 14 * u }}
                >
                  {i > 0 ? (
                    <span style={{ color: c.muted, opacity: 0.5 }}>→</span>
                  ) : null}
                  <span
                    style={{
                      color: active ? fg : c.muted,
                      opacity: active || done ? 1 : 0.45,
                    }}
                  >
                    {s}
                  </span>
                </div>
              );
            })}
          </div>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 10 * u,
              color: fg,
              fontWeight: 500,
              fontVariantNumeric: "tabular-nums",
            }}
          >
            <span
              style={{
                width: 10 * u,
                height: 10 * u,
                background: accent,
                opacity: focus,
              }}
            />
            <span>
              {tiles}{" "}
              <span style={{ color: c.muted, fontWeight: 400 }}>
                {tiles === 1 ? unit.replace(/s$/, "") : unit}
              </span>
            </span>
          </div>
        </div>
      </ScaleLayer>
      {grain ? <Grain opacity={c.grain} /> : null}
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  unit: {
    type: "text-content",
    default: "tiles",
    description: "Unit",
  },
  zoom: {
    type: "number",
    default: 2.8,
    min: 1,
    max: 5,
    step: 0.1,
    description: "Start zoom",
    hiddenFromList: false,
  },
  highlight: {
    type: "boolean",
    default: true,
    description: "Highlight first tile",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  fontFamily: {
    type: "font-family",
    default: "Schibsted Grotesk",
    description: "Font",
  },
  ink: {
    type: "color",
    default: undefined,
    description: "Text color",
  },
  background: {
    type: "color",
    default: undefined,
    description: "Background",
  },
  scale: {
    type: "number",
    default: 1,
    min: 0.5,
    max: 1.5,
    step: 0.05,
    description: "Scale",
    hiddenFromList: false,
  },
  delay: {
    type: "number",
    default: 0,
    min: 0,
    max: 60,
    step: 1,
    description: "Delay (frames)",
    hiddenFromList: false,
  },
  grain: {
    type: "boolean",
    default: true,
    description: "Grain",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","unit","zoom","highlight","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  unit: "tiles",
  zoom: 2.8,
  highlight: true,
  accent: "#3B5BFD",
  fontFamily: "Schibsted Grotesk",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type PatternTileElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof PatternTileBase>;

const PatternTileInner = forwardRef<
  HTMLDivElement,
  PatternTileElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<PatternTile>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <PatternTileBase
          {...(componentProps as unknown as ComponentProps<typeof PatternTileBase>)}
        />
      </div>
    </Sequence>
  );
});

export const PatternTile = Interactive.withSchema({
  Component: PatternTileInner,
  componentName: "<PatternTile>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
